// Junta o resultado dos dois blocos de purga em uma linha só, que é o que vai
// para o canal de operação. Nenhum dado removido aparece aqui: o relatório
// carrega contagem, prazo e alvo, e nada mais.
function primeira(nomeDoNo) {
  try {
    const itens = $(nomeDoNo).all();
    return itens.length ? itens[0].json : null;
  } catch (erro) {
    return null;
  }
}

const execucoes = primeira('Purgar Execuções com Erro (72h)');
const trilha = $json || null;

const linhas = [];
let total = 0;
let falhou = false;

for (const r of [execucoes, trilha]) {
  if (!r || r.linhas_removidas === undefined) {
    falhou = true;
    continue;
  }
  const n = Number(r.linhas_removidas) || 0;
  total += n;
  linhas.push(`• ${r.alvo} (${r.prazo}): ${n} removida(s)`);
}

// Um alerta que dispara todo dia vira ruído e deixa de ser lido. O relatório
// diário só vai ao canal quando houve remoção ou quando algum bloco falhou;
// nos demais dias, a execução fica registrada no histórico do n8n e basta.
const deveNotificar = falhou || total > 0;

return [{
  json: {
    executado_em: new Date().toISOString(),
    total_removido: total,
    detalhe: linhas.join('\n') || 'nenhum bloco retornou contagem',
    falhou,
    deve_notificar: deveNotificar,
    severidade: falhou ? 'P2' : 'informativo',
  },
}];

